parameters.query:
SELECT DISTINCT ON (symbol) id, symbol, price_json, news_json, created_at
FROM market_snapshots
ORDER BY symbol, created_at DESC;

parameters.jsCode:
const item = $input.first().json;
const symbol = item.symbol;
const price = typeof item.price_json === 'string' ? item.price_json : JSON.stringify(item.price_json);
const news = typeof item.news_json === 'string' ? item.news_json : JSON.stringify(item.news_json);
const model = $env.OLLAMA_MODEL || 'llama3.2';
const prompt = [
  'You are a trading assistant.',
  'Given price data and news headlines for ' + symbol + ',',
  'respond ONLY with valid JSON (no markdown):',
  '{"action":"BUY"|"SELL"|"HOLD","confidence":0-100,"reasoning":"..."}',
  '',
  'Price data: ' + price,
  '',
  'News: ' + news
].join('\n');
return [{ json: { symbol, model, prompt, price_json: item.price_json, news_json: item.news_json } }];

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const symbol = $('Build Ollama Prompt').item.json.symbol || $('Load Latest Snapshots').item.json.symbol;
  const rawResponse = item.json.response || '';
  let parsed = { action: 'HOLD', confidence: 0, reasoning: 'Failed to parse LLM response' };

  try {
    const jsonMatch = rawResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      parsed = JSON.parse(jsonMatch[0]);
    }
  } catch (e) {
    parsed.reasoning = 'Parse error: ' + e.message;
  }

  parsed.action = (parsed.action || 'HOLD').toUpperCase();
  if (!['BUY', 'SELL', 'HOLD'].includes(parsed.action)) parsed.action = 'HOLD';
  parsed.confidence = Math.min(100, Math.max(0, parseInt(parsed.confidence) || 0));
  parsed.symbol = symbol;
  parsed.raw_llm_response = rawResponse;

  results.push({ json: parsed });
}

return results;

parameters.query:
=INSERT INTO signals (symbol, action, confidence, reasoning, raw_llm_response)
VALUES ('{{ $json.symbol }}', '{{ $json.action }}', {{ $json.confidence }}, '{{ $json.reasoning.replace(/'/g, "''") }}', '{{ ($json.raw_llm_response || '').replace(/'/g, "''") }}')
RETURNING id;

